"""Offline analysis of the draws recorded by the consensus run (4b32c77, 5 draws/sample)."""
import sys, json, glob, collections, itertools, random

sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import get_evaluator
from answer_conventions import answer_items, final_answer_field, joining_separator
from answer_conventions import profile_from_memory


def load_memory(task):
    p = f"/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043/{task}/memory.json"
    return json.load(open(p))


def last_text(messages):
    if not messages:
        return ""
    m = messages[-1]
    content = m.get("content") if isinstance(m, dict) else getattr(m, "content", m)
    if isinstance(content, list):
        return "".join(p.get("text", "") if isinstance(p, dict) else str(p) for p in content)
    return content or ""


def draws_of(row):
    out = [last_text(row["messages"])]
    for sc in row.get("side_calls") or []:
        out.append(last_text(sc))
    return out


def gold(task, text, target):
    pred = extract_json_field(text, "final_answer")
    r = get_evaluator(task)(pred, target)
    return r["was_correct"] if isinstance(r, dict) else bool(r)


def key_of(text, composed):
    answer = final_answer_field(text)
    if not answer:
        import re
        return (re.sub(r"\s+", " ", (text or "").strip()).lower(),)
    if composed:
        items = tuple(sorted(i.lower() for i in answer_items(answer)))
        if items:
            return items
    import re
    return (re.sub(r"\s+", " ", answer.strip().lower()),)


def vote(texts, composed):
    groups = {}
    for t in texts:
        groups.setdefault(key_of(t, composed), []).append(t)
    return max(groups.values(), key=len)[0]


rows = collections.defaultdict(list)
for task in ["USPTO", "Symptom2Disease", "LawBench"]:
    composed = bool(joining_separator((profile_from_memory(load_memory(task)).get("answers") or {})))
    for f in sorted(glob.glob(f"/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043/{task}/conversations/*/sample-*.json")):
        if "/prepare/" in f:
            continue
        row = json.load(open(f))
        if row["status"] != "ok":
            continue
        ds = draws_of(row)
        rows[task].append((row, ds, composed))

print("=== per-draw vs vote ===")
for task, items in rows.items():
    ndraw = collections.Counter(len(d) for _, d, _ in items)
    single = [sum(gold(t, d, r["target"]) for d in ds) / len(ds) for r, ds, _ in items for t in [task]]
    allgood = [sum(1 for d in ds if gold(task, d, r["target"])) for r, ds, _ in items]
    voted = [gold(task, vote(ds, c), r["target"]) for r, ds, c in items]
    per_draw = sum(allgood) / sum(len(ds) for _, ds, _ in items)
    print(f"{task}: samples={len(items)} draws/sample={dict(ndraw)} per-draw acc={per_draw:.3f} vote-acc={sum(voted)/len(voted):.3f}")
    print(f"   mean draws correct per sample={sum(allgood)/len(allgood):.2f}")
    # oracle: any draw correct
    oracle = [1 if a else 0 for a in allgood]
    print(f"   any-draw-correct={sum(oracle)/len(oracle):.3f}")

print()
print("=== k-draw vote curve (sample k of the recorded draws without replacement) ===")
random.seed(0)
for task, items in rows.items():
    line = []
    for k in range(1, 6):
        accs = []
        for r, ds, c in items:
            if len(ds) < k:
                continue
            combos = list(itertools.combinations(range(len(ds)), k))
            vals = [gold(task, vote([ds[i] for i in combo], c), r["target"]) for combo in combos]
            accs.append(sum(vals) / len(vals))
        line.append(f"k={k}:{sum(accs)/len(accs):.3f}")
    print(task, " ".join(line))

print()
print("=== item-level majority over draws (composed tasks) ===")
for task, items in rows.items():
    if task == "Symptom2Disease":
        continue
    acc, tot, changed = 0, 0, 0
    for r, ds, c in items:
        sets = [tuple(sorted(i.lower() for i in answer_items(final_answer_field(d) or d))) for d in ds]
        cnt = collections.Counter(i for s in sets for i in s)
        n = len(sets)
        keep = sorted(i for i, k in cnt.items() if k * 2 > n)
        if not keep:
            keep = sorted(collections.Counter(sets).most_common(1)[0][0])
        # rebuild the answer text as the harness writes it: items joined by the memory's separator
        sep = "." if task == "USPTO" else "、"
        text = json.dumps({"final_answer": sep.join(keep)}, ensure_ascii=False)
        acc += gold(task, text, r["target"])
        tot += 1
        changed += keep != list(sets[0])
    print(f"{task}: item-majority acc={acc/tot:.3f} over {tot}")

