"""Offline analysis of the draws recorded by the consensus run (4b32c77, 5 draws/sample).

The folded conversation keeps the main line plus every independent line the framework saw,
including prefixes of the same draw, so a draw is recovered as a maximal line.
"""
import sys, json, glob, collections, itertools, random, re

sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import get_evaluator
from answer_conventions import answer_items, final_answer_field, joining_separator

RUN = "/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043"


def text_of(m):
    c = m.get("content") if isinstance(m, dict) else getattr(m, "content", m)
    if isinstance(c, list):
        return "".join(p.get("text", "") if isinstance(p, dict) else str(p) for p in c)
    return c or ""


def sig(m):
    calls = tuple(
        (tc.get("function", {}).get("name"), tc.get("function", {}).get("arguments"))
        for tc in (m.get("tool_calls") or [])
    )
    return (m.get("role"), text_of(m), calls)


def draw_answers(row):
    lines = [row["messages"]] + list(row.get("side_calls") or [])
    sigs = [[sig(m) for m in line] for line in lines]
    maximal = []
    for i, s in enumerate(sigs):
        if any(j != i and len(t) > len(s) and t[: len(s)] == s for j, t in enumerate(sigs)):
            continue
        last = [m for m in lines[i] if m.get("role") == "assistant"]
        if last:
            maximal.append(last[-1])
    return [text_of(m) for m in maximal]


def gold(task, text, target):
    pred = extract_json_field(text, "final_answer")
    r = get_evaluator(task)(pred, target)
    return r["was_correct"] if isinstance(r, dict) else bool(r)


def key_of(text, composed):
    answer = final_answer_field(text)
    if not answer:
        return (re.sub(r"\s+", " ", (text or "").strip()).lower(),)
    if composed:
        items = tuple(sorted(i.lower() for i in answer_items(answer)))
        if items:
            return items
    return (re.sub(r"\s+", " ", answer.strip().lower()),)


def vote(texts, composed):
    groups = {}
    for t in texts:
        groups.setdefault(key_of(t, composed), []).append(t)
    return max(groups.values(), key=len)[0]


data = {}
for task in ["USPTO", "Symptom2Disease", "LawBench"]:
    prof = json.load(open(f"{RUN}/{task}/memory.json")).get("answer_profile") or {}
    composed = bool(joining_separator(prof.get("answers") or {}))
    items = []
    for f in sorted(glob.glob(f"{RUN}/{task}/conversations/*/sample-*.json")):
        if "/prepare/" in f:
            continue
        row = json.load(open(f))
        if row["status"] != "ok":
            continue
        items.append((row, draw_answers(row), composed))
    data[task] = items

print("=== draws recovered per sample ===")
for task, items in data.items():
    print(task, dict(collections.Counter(len(d) for _, d, _ in items)))

print("\n=== per-draw vs vote vs recorded ===")
for task, items in data.items():
    allgood = [sum(1 for d in ds if gold(task, d, r["target"])) for r, ds, _ in items]
    voted = [gold(task, vote(ds, c), r["target"]) for r, ds, c in items]
    recorded = [r["was_correct"] for r, ds, _ in items]
    per_draw = sum(allgood) / sum(len(ds) for _, ds, _ in items)
    print(f"{task}: samples={len(items)} per-draw={per_draw:.3f} vote={sum(voted)/len(voted):.3f} recorded={sum(recorded)/len(recorded):.3f} any-draw={sum(1 for a in allgood if a)/len(allgood):.3f}")

print("\n=== k-draw vote curve over the recovered draws (all subsets) ===")
for task, items in data.items():
    line = []
    for k in range(1, 6):
        accs = []
        for r, ds, c in items:
            if len(ds) < k:
                continue
            vals = [gold(task, vote([ds[i] for i in combo], c), r["target"]) for combo in itertools.combinations(range(len(ds)), k)]
            accs.append(sum(vals) / len(vals))
        line.append(f"k={k}:{sum(accs)/len(accs):.3f}")
    print(task, " ".join(line), f"(n={len(items)})")

print("\n=== item-level majority (composed tasks) ===")
for task in ["USPTO", "LawBench"]:
    items = data[task]
    sep = "." if task == "USPTO" else "、"
    acc = tot = 0
    for r, ds, c in items:
        sets = [tuple(sorted(i.lower() for i in answer_items(final_answer_field(d) or d))) for d in ds]
        if not sets:
            continue
        cnt = collections.Counter(i for s in sets for i in s)
        n = len(sets)
        keep = sorted(i for i, k in cnt.items() if k * 2 > n) or sorted(collections.Counter(sets).most_common(1)[0][0])
        text = json.dumps({"final_answer": sep.join(keep)}, ensure_ascii=False)
        acc += gold(task, text, r["target"])
        tot += 1
    print(f"{task}: item-majority acc={acc/tot:.3f} over {tot}")

print("\n=== how many draws agree with the vote / spreads ===")
for task, items in data.items():
    spreads = collections.Counter(len({key_of(d, c) for d in ds}) for r, ds, c in items)
    print(task, "distinct answers per sample:", dict(sorted(spreads.items())))

