"""Compare aggregation rules over the draws recovered from the consensus run."""
import sys, json, glob, collections, itertools, re

sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import get_evaluator
from answer_conventions import answer_items, final_answer_field, joining_separator

RUN = "/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043"


def text_of(m):
    c = m.get("content") if isinstance(m, dict) else getattr(m, "content", m)
    if isinstance(c, list):
        return "".join(p.get("text", "") if isinstance(p, dict) else str(p) for p in c)
    return c or ""


def sig(m):
    return (m.get("role"), text_of(m), tuple((tc.get("function", {}).get("name"), tc.get("function", {}).get("arguments")) for tc in (m.get("tool_calls") or [])))


def draw_answers(row):
    lines = [row["messages"]] + list(row.get("side_calls") or [])
    sigs = [[sig(m) for m in line] for line in lines]
    out = []
    for i, s in enumerate(sigs):
        if any(j != i and len(t) > len(s) and t[: len(s)] == s for j, t in enumerate(sigs)):
            continue
        last = [m for m in lines[i] if m.get("role") == "assistant"]
        if last:
            out.append(text_of(last[-1]))
    return out


def gold(task, text, target):
    r = get_evaluator(task)(extract_json_field(text, "final_answer"), target)
    return r["was_correct"] if isinstance(r, dict) else bool(r)


def items_of(text):
    return tuple(sorted(i.lower() for i in answer_items(final_answer_field(text) or text)))


def unit_of(text, composed):
    answer = final_answer_field(text)
    if answer and composed:
        it = items_of(text)
        if it:
            return it
    return (re.sub(r"\s+", " ", (final_answer_field(text) or text or "").strip().lower()),)


def vote_plurality(draws, composed):
    groups = collections.defaultdict(list)
    for d in draws:
        groups[unit_of(d, composed)].append(d)
    return max(groups.values(), key=len)[0]


def vote_centroid(draws, composed):
    """The draw whose unit agrees most with the other draws, counted per unit."""
    units = [unit_of(d, composed) for d in draws]
    def sim(a, b):
        sa, sb = set(a), set(b)
        return len(sa & sb) / len(sa | sb) if sa | sb else 1.0
    groups = {}
    for d, u in zip(draws, units):
        groups.setdefault(u, []).append(d)
    best, best_score = None, -1
    for u, members in groups.items():
        score = sum(sim(u, other) for other in units)
        if score > best_score:
            best, best_score = members[0], score
    return best


def vote_top_then_centroid(draws, composed):
    """Plurality; among ties (and only ties) the unit closest to the others."""
    groups = collections.defaultdict(list)
    for d in draws:
        groups[unit_of(d, composed)].append(d)
    top = max(len(v) for v in groups.values())
    tied = [v for v in groups.values() if len(v) == top]
    if len(tied) == 1:
        return tied[0][0]
    return vote_centroid([v[0] for v in tied], composed)


def vote_most_agreed_items(draws, composed, floor=2):
    """The set of items that at least `floor` draws carry (fallback: plurality)."""
    if not composed:
        return vote_plurality(draws, composed)
    sets = [items_of(d) for d in draws]
    cnt = collections.Counter(i for s in sets for i in s)
    keep = sorted(i for i, k in cnt.items() if k >= floor)
    if not keep:
        return vote_plurality(draws, composed)
    return json.dumps({"final_answer": "." .join(keep) if all("." in s for s in []) else "、".join(keep)}, ensure_ascii=False)


data = {}
for task in ["USPTO", "Symptom2Disease", "LawBench"]:
    prof = json.load(open(f"{RUN}/{task}/memory.json")).get("answer_profile") or {}
    composed = bool(joining_separator(prof.get("answers") or {}))
    items = []
    for f in sorted(glob.glob(f"{RUN}/{task}/conversations/*/sample-*.json")):
        if "/prepare/" in f:
            continue
        row = json.load(open(f))
        if row["status"] != "ok":
            continue
        items.append((row, draw_answers(row), composed))
    data[task] = items

rules = {
    "plurality (current)": vote_plurality,
    "centroid": vote_centroid,
    "plurality+centroid tiebreak": vote_top_then_centroid,
}

print(f"{'task':18s} {'n':>4s} " + " ".join(f"{name[:22]:>24s}" for name in rules))
for task, items in data.items():
    full = [(r, d, c) for r, d, c in items if len(d) >= 5]
    row = []
    for name, rule in rules.items():
        acc = sum(gold(task, rule(ds, c), r["target"]) for r, ds, c in full) / len(full)
        row.append(f"{acc:>24.3f}")
    print(f"{task:18s} {len(full):>4d} " + " ".join(row))

# k-curve per rule on samples with 5 draws
print("\nk-draw curve (samples with 5 draws, all subsets)")
for task, items in data.items():
    full = [(r, d, c) for r, d, c in items if len(d) >= 5]
    print(task)
    for name, rule in rules.items():
        line = []
        for k in range(1, 6):
            accs = [sum(gold(task, rule([ds[i] for i in combo], c), r["target"]) for combo in itertools.combinations(range(5), k)) / len(list(itertools.combinations(range(5), k))) for r, ds, c in full]
            line.append(f"k={k}:{sum(accs)/len(accs):.3f}")
        print("   ", name, " ".join(line))

