sys.path.insert(0, "/workspace")
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import get_evaluator
from answer_conventions import final_answer_field

RUN = "/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043"


def text_of(m):
    c = m.get("content") if isinstance(m, dict) else getattr(m, "content", m)
    if isinstance(c, list):
        return "".join(p.get("text", "") if isinstance(p, dict) else str(p) for p in c)
    return c or ""


def sig(m):
    return (m.get("role"), text_of(m), tuple((tc.get("function", {}).get("name"), tc.get("function", {}).get("arguments")) for tc in (m.get("tool_calls") or [])))


def lines_of(row):
    lines = [row["messages"]] + list(row.get("side_calls") or [])
    sigs = [[sig(m) for m in line] for line in lines]
    return [line for i, line in enumerate(lines) if not any(j != i and len(t) > len(sigs[i]) and t[: len(sigs[i])] == sigs[i] for j, t in enumerate(sigs))]


def gold(task, text, target):
