notice_kind = collections.Counter()
flips = collections.Counter()
per_task = collections.defaultdict(collections.Counter)
for task in ["USPTO", "Symptom2Disease", "LawBench"]:
    for f in sorted(glob.glob(f"{RUN}/{task}/conversations/*/sample-*.json")):
        if "/prepare/" in f:
