        for line in lines_of(row):
            for i in range(1, len(line) - 1):
                if line[i].get("role") == "user" and line[i - 1].get("role") == "assistant":
                    notice = text_of(line[i])
                    kind = ("reading" if notice.startswith("You are about to finish")
                            else "form" if notice.startswith("Your reply did not state")
                            else "wording" if notice else "other")
                    notice_kind[kind] += 1
                    before = text_of(line[i - 1])
