                    same = final_answer_field(before).strip() == final_answer_field(after).strip()
                    per_task[task][f"{kind}:{'same' if same else 'changed'}:{'kept-ok' if gb and ga else 'ok->bad' if gb else 'bad->ok' if ga else 'bad->bad'}"] += 1
                    flips[(kind, gb, ga)] += 1

