    fixed = sum(v for (k, b, a), v in flips.items() if k == kind and not b and a)
    broke = sum(v for (k, b, a), v in flips.items() if k == kind and b and not a)
    kept = sum(v for (k, b, a), v in flips.items() if k == kind and b and a)
    bad = sum(v for (k, b, a), v in flips.items() if k == kind and not b and not a)
    print(f"{kind}: {tot} turns | wrong->right {fixed} | right->wrong {broke} | right->right {kept} | wrong->wrong {bad}")
print()
for task, c in per_task.items():
    print(task, {k: v for k, v in sorted(c.items())})

