sys.path.insert(0, "/workspace")
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import get_evaluator
from answer_conventions import final_answer_field, answer_items, joining_separator

RUN = "/workspace/runs/4b32c77ad6d053ba5a659c5ffad4a41250700043"


def text_of(m):
    c = m.get("content") if isinstance(m, dict) else getattr(m, "content", m)
    if isinstance(c, list):
        return "".join(p.get("text", "") if isinstance(p, dict) else str(p) for p in c)
    return c or ""


def sig(m):
    return (m.get("role"), text_of(m), tuple((tc.get("function", {}).get("name"), tc.get("function", {}).get("arguments")) for tc in (m.get("tool_calls") or [])))


def lines_of(row):
    lines = [row["messages"]] + list(row.get("side_calls") or [])
    sigs = [[sig(m) for m in line] for line in lines]
    return [line for i, line in enumerate(lines) if not any(j != i and len(t) > len(sigs[i]) and t[: len(sigs[i])] == sigs[i] for j, t in enumerate(sigs))]


def gold(task, text, target):
    r = get_evaluator(task)(extract_json_field(text, "final_answer"), target)
    return r["was_correct"] if isinstance(r, dict) else bool(r)


def key_of(text, composed):
    answer = final_answer_field(text)
    if not answer:
        return (re.sub(r"\s+", " ", (text or "").strip()).lower(),)
    if composed:
        it = tuple(sorted(i.lower() for i in answer_items(answer)))
        if it:
            return it
    return (re.sub(r"\s+", " ", answer.strip().lower()),)


def vote(texts, composed):
    groups = collections.defaultdict(list)
    for t in texts:
        groups[key_of(t, composed)].append(t)
    return max(groups.values(), key=len)[0]


for task in ["USPTO", "Symptom2Disease", "LawBench"]:
    prof = json.load(open(f"{RUN}/{task}/memory.json")).get("answer_profile") or {}
    composed = bool(joining_separator(prof.get("answers") or {}))
    asis = first = 0
    n = fire = 0
    for f in sorted(glob.glob(f"{RUN}/{task}/conversations/*/sample-*.json")):
        if "/prepare/" in f:
            continue
        row = json.load(open(f))
        if row["status"] != "ok":
            continue
        target = row["target"]
        draws, draws_first = [], []
        for line in lines_of(row):
            # the answer as recorded
            assistants = [m for m in line if m.get("role") == "assistant"]
            if not assistants:
                continue
            draws.append(text_of(assistants[-1]))
            # the first answer of that line, before any reading/form/wording notice
            firsts = []
            for i, m in enumerate(line):
                if m.get("role") == "assistant":
                    firsts.append(text_of(m))
                    if i + 1 < len(line) and line[i + 1].get("role") == "user" and _ := text_of(line[i + 1]):
                        pass
            # first answer = the assistant message before the first injected notice
            pre = None
            for i, m in enumerate(line):
                if m.get("role") == "assistant":
                    if pre is None:
                        pre = text_of(m)
                elif m.get("role") == "user" and i > 1:
                    break
            draws_first.append(pre if pre is not None else text_of(assistants[-1]))
        n += 1
        fire += sum(1 for a, b in zip(draws, draws_first) if a != b)
        asis += gold(task, vote(draws, composed), target)
        first += gold(task, vote(draws_first, composed), target)
    print(f"{task}: samples={n} draws changed by a notice={fire} | vote as recorded={asis/n:.3f} | vote with pre-notice answers={first/n:.3f}")

